/// The fine grain of a surface, roughly −1..1.
///
/// Three octaves at **co-prime** lattices. Two an exact factor apart put their features on the same
/// grid and read as a woven cross-hatch rather than as a material — the defect that made this
/// engine's first generated stone look like bathroom tile.
fn grain(seed: u64, u: f32, v: f32) -> f32 {
    noise::octaves(
        seed,
        u,
        v,
        // **A fourth octave, and it is the one a player actually stands in front of.** Engine gate
        // review 20 measured a 120x90 patch of near lining with **61.7% of it inside one 16-level
        // band** and went to the source rather than judging from the render: the lining tile covers
        // 3.6 m, so at two metres it is magnified past its own finest feature and flattens to a
        // single value. Three octaves topping out at a lattice of 43 give features about 12 texels
        // across at 512; 127 gives features a few texels across at 1024, which is the scale that
        // survives being walked up to. Still co-prime with the others, for the reason below.
        &[(7, 0.46), (17, 0.28), (43, 0.16), (127, 0.10)],
    )
}

/// A slow drift across the whole tile, at a period unrelated to any lattice on it.
///
/// **The half a lattice cannot supply.** Even with every piece a different size, a tile of uniform
/// average brightness repeats visibly across a long tunnel, because the eye finds the period. Light
/// and dark regions *across* pieces are what damp and age actually do.
fn macro_tint(seed: u64, u: f32, v: f32) -> f32 {
    noise::tiling(seed ^ 0x4D_AC_C0, u, v, 3) * 0.5
        + noise::tiling(seed ^ 0x4D_AC_C1, u, v, 5) * 0.5
}

/// How much of a bolt head covers this point, `0.0` clear and `1.0` at the centre of one.
///
/// Bolts sit in a row just inside each circumferential joint, which is where a cast-iron ring is
/// actually flanged and bolted. Returning coverage rather than a boolean is what keeps the edge
/// from aliasing into a ring of stairsteps at a grazing angle.
fn bolt(surface: &Surface, wall: &Wall, u: f32, v: f32) -> f32 {
    let Some((count, radius, _)) = surface.bolts else {
        return 0.0;
    };
    let count = count.max(1);

    // The nearest circumferential joint, and how far from it this point is. Bolts hug the joint on
    // the ring's own side of it, so the offset is signed and taken twice — once per side.
    let mut closest = f32::MAX;
    for row in 0..wall.rows() {
        let (low, high) = wall.extent(row);
        for edge in [low, high] {
            let gap = (v - edge).abs();
            closest = closest.min(gap.min(1.0 - gap));
        }
    }

    // Just inside the joint rather than on it: a bolt through the middle of a joint would read as a
    // rivet holding nothing, and one far inside reads as a stud on a panel rather than as a fixing
    // through a flange. **The first attempt used 2.2 radii and the bolts came out as domino pips**
    // a quarter of the way into each segment.
    let inset = radius * 1.25;
    let across_joint = (closest - inset).abs();
    if across_joint > radius {
        return 0.0;
    }

    // Along the ring, bolts at a fixed pitch. `count` of them around the tile, which at the lining's
    // uv_scale is a bolt about every 20 cm.
    let pitch = 1.0 / f32::from(u16::try_from(count).unwrap_or(9));
    let along = (u.rem_euclid(pitch) / pitch - 0.5) * pitch;

    let distance = (along * along + across_joint * across_joint).sqrt();
    // A domed head: full height at the centre, falling to nothing at the rim. A paraboloid rather
    // than a power curve, because `powf` is what ADR 0044 bans and there is no reason to spend the
    // generation-time exemption on a bolt when a multiply gives the same silhouette.
    let t = (distance / radius).clamp(0.0, 1.0);
    1.0 - t * t
}

/// **The single height field all three maps are read off.**
///
/// Units are arbitrary; only differences matter, since the normal map is its gradient.
fn height(surface: &Surface, u: f32, v: f32) -> f32 {
    let joint = surface
        .wall
        .as_ref()
        .map_or(0.0, |wall| wall.at(u, v).joint);
    let stud = surface
        .wall
        .as_ref()
        .map_or(0.0, |wall| bolt(surface, wall, u, v));
    let raised = surface.bolts.map_or(0.0, |(_, _, height)| height) * stud;

    // **Pitting, at the same lattice the speckle uses.** A dirt mark that exists only in the albedo
    // is flat under any light, so a patch of wall two metres away still resolves to one value however
    // much colour variation it carries -- which is why engine gate review 22's band measure barely
    // moved when the albedo speckle was added. Feeding the same field into the height gives it a
    // normal, so it shades per pixel, and paint over iron really does pit rather than just soil.
    let pitting = noise::tiling(surface.seed ^ 0x5E_CC_1E, u, v, 288) * 0.5 + 0.5;
    let pitting = ((pitting - 0.5) / 0.5).clamp(0.0, 1.0);

    // The joint is cut *into* the surface and the bolt stands *out* of it. The grain is a fraction of
    // either, which is what keeps it from competing with the shapes that carry the read.
    grain(surface.seed, u, v) * 0.030 - pitting * 0.016 - joint + raised
}

/// Where the paint has worn through, `0..1`.
///
/// Concentrated at joints and on bolt heads — the two places a painted casting is actually handled,
/// knocked and rubbed. Plus a low-frequency patch field, so there are worn *areas* rather than an
/// even speckle, which is the difference between weathering and dirt.
fn worn(surface: &Surface, u: f32, v: f32) -> f32 {
    let joint = surface
        .wall
        .as_ref()
        .map_or(0.0, |wall| wall.at(u, v).joint);
    let stud = surface
        .wall
        .as_ref()
        .map_or(0.0, |wall| bolt(surface, wall, u, v));

    // **Thresholded, not scaled**, and the first version got this wrong in a way worth recording.
    //
    // It cubed a `0..1` patch field, summed it with the joint and stud terms, and multiplied the lot
    // by a fine grain. Every one of those steps is a *scale*, so the result was rust everywhere at
    // about a tenth strength: the whole 512² tile spanned luma 155-210 with red ahead of blue by a
    // constant twelve levels. That is not white paint over rust. It is pink.
    //
    // What is wanted is most of the wall clean and a minority of it properly bare. So the patch
    // field is cut at a threshold and re-normalised over what is left, which makes the worn areas
    // rare *and* strong instead of universal and weak.
    let patch = (noise::tiling(surface.seed ^ 0x9E11, u, v, 7) * 0.5 + 0.5).clamp(0.0, 1.0);
    let patchy = ((patch - 0.74) / 0.22).clamp(0.0, 1.0);
    // The fine grain breaks the patch's *edge* rather than dimming its middle — a hard-edged rust
    // patch reads as a sticker, and a uniformly dimmed one reads as a tint.
    let edge = (grain(surface.seed ^ 0x2C77, u, v) * 0.5 + 0.5).clamp(0.0, 1.0);
    let patchy = (patchy * (0.55 + 0.9 * edge)).clamp(0.0, 1.0);

    // Joints and bolt heads are where a painted casting is actually handled, knocked and rubbed.
    let handled = (joint * 0.85 + stud * 0.7).clamp(0.0, 1.0);

    // **`max`, not a sum.** Adding them means a patch *over* a joint compounds to full rust and,
    // worse, that every point gets a little of both — which is the uniform wash again.
    (patchy.max(handled) * surface.wear).clamp(0.0, 1.0)
}

/// How dirty this point is, `0.0` clean and `1.0` as dirty as [`Surface::grime`] allows.
///
/// Two sources, combined with `max` for [`worn`]'s reason — summing them gives every point a little
/// of both, which is the uniform wash all over again.
///
/// **Settled dirt** is a low-frequency field cut at a threshold, so most of a plate is merely dusty
/// and a minority of it is properly filthy. **Recess dirt** is the joints and the ring around each
/// bolt head, because those are the two places on a bolted casting that cannot be wiped.
fn grimy(surface: &Surface, u: f32, v: f32) -> f32 {
    let settled = (noise::tiling(surface.seed ^ 0x6D_11_7A, u, v, 4) * 0.5 + 0.5).clamp(0.0, 1.0);
    // Re-normalised over the top two thirds rather than scaled, so the clean parts stay clean.
    let settled = ((settled - 0.32) / 0.55).clamp(0.0, 1.0);

    // A second, finer field breaks the first one's edge, so a dirty patch does not read as a decal.
    let broken = (grain(surface.seed ^ 0x6D_12, u, v) * 0.5 + 0.5).clamp(0.0, 1.0);
    let settled = (settled * (0.5 + 0.85 * broken)).clamp(0.0, 1.0);

    // **And a fine speckle, which is the half that survives being walked up to.** Engine gate review
    // 20 measured 61.7% of a 120x90 patch of near lining inside one 16-level band and traced it to
    // the source: the tile's own detail was all low-frequency, so magnifying it flattened the lot.
    // Raising the frequency alone did not fix it -- a fourth octave at lattice 127 moved that figure
    // by 0.4 of a per cent -- because the amplitude was never there. Soot and dust are speckle, not a
    // wash, so this is thresholded hard and applied at strength.
    // **Two lattices, and the fine one is the point.** At 1024 a lattice of 96 gives features about
    // eleven texels across, which is still low-frequency once a player standing two metres away
    // magnifies the tile: engine gate review 22 measured 51.1% of a near-wall patch inside one
    // 16-level band even after the amplitude fix, and said what was missing was *per-texel* grain.
    // 288 gives features under four texels and 704 gives them at about one and a half.
    let speckle = (noise::tiling(surface.seed ^ 0x5E_CC_1E, u, v, 288) * 0.5 + 0.5).clamp(0.0, 1.0);
    let speckle = ((speckle - 0.5) / 0.5).clamp(0.0, 1.0);
    let dust = (noise::tiling(surface.seed ^ 0x5E_CC_2F, u, v, 704) * 0.5 + 0.5).clamp(0.0, 1.0);
    let dust = ((dust - 0.62) / 0.38).clamp(0.0, 1.0);
    let settled = settled.max(speckle * 0.8).max(dust * 0.95);

    let recess = surface.wall.as_ref().map_or(0.0, |wall| {
        let joint = wall.at(u, v).joint;
        let stud = bolt(surface, wall, u, v);
        // The bolt's *rim*, not its dome: dirt collects around a raised head, not on top of it.
        let rim = (stud * (1.0 - stud) * 4.0).clamp(0.0, 1.0);
        (joint * 0.9).max(rim * 0.75)
    });

    settled.max(recess)
}

/// The base colour map, in sRGB.
fn render_colour(surface: &Surface) -> Canvas {
    let mut canvas = Canvas::new(SIZE, Space::Srgb);
    canvas.fill(|u, v| {
        let (u, v) = surface.axes(u, v);
        let t = (grain(surface.seed, u, v) * 0.5 + 0.5).clamp(0.0, 1.0);
        let drift = macro_tint(surface.seed, u, v) * 0.14;
        let tone = surface.wall.as_ref().map_or(0.0, |wall| {
            (wall.tone(wall.at(u, v), 0) - 0.5) * 2.0 * surface.tone_variation
        });
        let through = worn(surface, u, v);
        let dirt = grimy(surface, u, v);

        let mut colour = [0.0; 4];
        for (channel, out) in colour.iter_mut().take(3).enumerate() {
            let base = surface.low[channel] + (surface.high[channel] - surface.low[channel]) * t;
            let varied = (base * (1.0 + tone + drift)).clamp(0.0, 1.0);
            // The paint over the rust, rather than the rust over the paint: `through` is how much of
            // what is underneath has been exposed.
            let exposed = (varied + (surface.beneath[channel] - varied) * through).clamp(0.0, 1.0);
            // Dirt sits **on** the surface, so it darkens whatever is showing — paint or the rust
            // under it — rather than being mixed into the paint colour.
            *out = (exposed * (1.0 - surface.grime * dirt)).clamp(0.0, 1.0);
        }
        colour[3] = 1.0;
        colour
    });
    canvas
}

/// The tangent-space normal map, in **linear** bytes.
fn render_normal(surface: &Surface) -> Canvas {
    let mut canvas = Canvas::new(SIZE, Space::Linear);
    let step = 1.0 / f32::from(u16::try_from(SIZE).unwrap_or(512));
    canvas.fill(|u, v| {
        let field = |x: f32, y: f32| {
            let (x, y) = surface.axes(x, y);
            height(surface, x, y)
        };
        maps::encode_normal(maps::normal_from_height(&field, u, v, step, surface.relief))
    });
    canvas
}

/// The occlusion-metallic-roughness map, in **linear** bytes.
///
/// glTF 2.0's packing, which the engine follows rather than invents: **red is occlusion**, green is
/// roughness, blue is metallic.
fn render_surface_map(surface: &Surface) -> Canvas {
    let mut canvas = Canvas::new(SIZE, Space::Linear);
    // Wide enough to span a joint, narrow enough to stay inside a segment.
    const RADIUS: f32 = 0.012;
    const STRENGTH: f32 = 0.6;

    canvas.fill(|u, v| {
        let field = |x: f32, y: f32| {
            let (x, y) = surface.axes(x, y);
            height(surface, x, y)
        };
        let occlusion = maps::cavity_from_height(&field, u, v, RADIUS, STRENGTH);

        let (u, v) = surface.axes(u, v);
        let joint = surface
            .wall
            .as_ref()
            .map_or(0.0, |wall| wall.at(u, v).joint);
        let through = worn(surface, u, v);
        let jitter = grain(surface.seed ^ 0x5B7D, u, v) * 0.05;
        // Worn metal is rougher than the paint that was on it, so exposure raises roughness as well
        // as changing the colour. Without this the rust reads as a decal rather than as a surface.
        let mut roughness = surface.face_roughness
            + (surface.joint_roughness - surface.face_roughness) * joint.max(through)
            + jitter;

        // **Damp and handling, which is what a flat roughness map is missing.**
        //
        // Engine gate review 16 probed all six of these textures and found roughness varying by at
        // most six levels *within* any one of them, and occlusion a constant 255 in five of the six.
        // Materials differed from each other and no material differed from itself, which is the
        // standard tell: uniform roughness is what says "computer-generated", because the variation
        // is the part that tells a story — water runs down, hands polish what they touch, dust
        // settles in what faces up.
        //
        // Two low-frequency fields, unrelated to each other and to any lattice. `damp` makes broad
        // wet patches *smoother*; `dust` makes broad settled patches *rougher* and darkens their
        // occlusion, because dirt in a recess is exactly what an occlusion map is for. Both are
        // deliberately larger than a plate, so the variation reads across a wall rather than as
        // speckle on one piece.
        let damp = noise::tiling(surface.seed ^ 0x0D_A3_71, u, v, 3) * 0.5 + 0.5;
        let dust = noise::tiling(surface.seed ^ 0x0D_05_72, u, v, 5) * 0.5 + 0.5;
        roughness += 0.20 * dust - 0.26 * damp;

        // Dirt collects where the surface is already occluded and where it faces the settling; a
        // clean face keeps its full 1.0 so nothing is darkened for its own sake.
        let occlusion = occlusion * (1.0 - 0.28 * dust);

        maps::pack_orm(occlusion, roughness, surface.metallic)
    });
    canvas
}

/// Writes one surface's three maps and their sidecars.
fn write_set(out: &Path, id: &str, surface: &Surface) {
    write(
        &out.join(format!("{id}.png")),
        id,
        render_colour(surface),
        Space::Srgb,
    );
    write(
        &out.join(format!("{id}_normal.png")),
        &format!("{id}_normal"),
        render_normal(surface),
        Space::Linear,
    );
    write(
        &out.join(format!("{id}_surface.png")),
        &format!("{id}_surface"),
        render_surface_map(surface),
        Space::Linear,
    );
}

/// Writes one image and the sidecar that says what colour space it is in.
fn write(path: &Path, id: &str, canvas: Canvas, space: Space) {
    let bytes = match canvas.encode() {
        Ok(bytes) => bytes,
        Err(error) => {
            eprintln!("could not encode {}: {error}", path.display());
            std::process::exit(1);
        }
    };
    if let Err(error) = std::fs::write(path, &bytes) {
        eprintln!("could not write {}: {error}", path.display());
        std::process::exit(1);
    }

    // **Q31's trap**: nothing inside a PNG says whether its bytes are colour or data, so the sidecar
    // is the only thing that does — and a normal map read through the sRGB curve has every direction
    // bent, silently. `Space::sidecar` keeps the two statements together.
    let sidecar = path.with_extension("png.ama-meta");
    let contents = match space.sidecar() {
        Some(declared) => format!("id = \"{id}\"\ncolor_space = \"{declared}\"\n"),
        None => format!("id = \"{id}\"\n"),
    };
    if let Err(error) = std::fs::write(&sidecar, contents) {
        eprintln!("could not write {}: {error}", sidecar.display());
        std::process::exit(1);
    }

    println!("wrote {} ({} bytes)", path.display(), bytes.len());
}

/// This crate's directory, so the binary can be run from anywhere.
fn manifest_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}
